RUNNER_TESTES_PARALELOS = '"""Validação integral em processos separados, sem dependências adicionais."""\nfrom __future__ import annotations\n\nimport argparse\nfrom collections import Counter, defaultdict\nfrom contextlib import redirect_stderr, redirect_stdout\nimport io\nimport json\nimport os\nfrom pathlib import Path\nimport queue\nimport subprocess\nimport sys\nimport threading\nimport time\n\n\ndef gravar(caminho, dados):\n    temporario = caminho.with_suffix(caminho.suffix + \'.tmp\')\n    temporario.write_text(json.dumps(dados, ensure_ascii=False, indent=2), encoding=\'utf-8\')\n    os.replace(temporario, caminho)\n\n\ndef argumentos_pytest():\n    return [\'tests\', \'-o\', \'addopts=\', \'--ignore=tests/mold\', \'-p\', \'no:cacheprovider\']\n\n\nclass Coletor:\n    def __init__(self): self.ids = []; self.arquivos = {}\n\n    def pytest_collection_finish(self, session):\n        for item in session.items:\n            self.ids.append(item.nodeid)\n            self.arquivos[item.nodeid] = str(item.path.resolve())\n\n\nclass Grupo:\n    def __init__(self, manifesto, numero, destino):\n        self.manifesto = manifesto; self.numero = numero; self.destino = destino\n        self.selecionados = []; self.fases = defaultdict(dict); self.chamadas = Counter()\n        self.coletados = []\n\n    def pytest_collection_modifyitems(self, config, items):\n        import pytest\n        self.coletados = [item.nodeid for item in items]\n        if Counter(self.coletados) != Counter(self.manifesto[\'coletados\']):\n            raise pytest.UsageError(\'A coleção mudou entre a conferência e o grupo de testes.\')\n        alvo = set(self.manifesto[\'grupos\'][str(self.numero)])\n        selecionados = [item for item in items if item.nodeid in alvo]\n        retirados = [item for item in items if item.nodeid not in alvo]\n        if Counter(item.nodeid for item in selecionados) != Counter(alvo):\n            raise pytest.UsageError(\'Grupo incompleto ou com testes duplicados.\')\n        self.selecionados = [item.nodeid for item in selecionados]\n        items[:] = selecionados\n        config.hook.pytest_deselected(items=retirados)\n\n    def pytest_runtest_logreport(self, report):\n        self.fases[report.nodeid][report.when] = report.outcome\n        if report.when == \'call\': self.chamadas[report.nodeid] += 1\n\n    def pytest_sessionfinish(self, session, exitstatus):\n        gravar(self.destino, {\'grupo\': self.numero, \'return_code\': int(exitstatus),\n            \'coletados\': self.coletados, \'selecionados\': self.selecionados,\n            \'fases\': dict(self.fases), \'chamadas\': dict(self.chamadas)})\n\n\ndef executar_grupo(args):\n    import pytest\n    manifesto = json.loads((args.trabalho / \'colecao.json\').read_text(encoding=\'utf-8\'))\n    diretorio = args.trabalho / (\'grupo_\' + str(args.grupo))\n    diretorio.mkdir()\n    # Os dois bancos globais e todas as pastas temporárias pertencem somente a este grupo.\n    os.environ.update(MEC_URL_BANCO_DADOS=\'sqlite:///\' + (diretorio / \'negocio.db\').as_posix(),\n        MEC_ACESSOS_DB=str(diretorio / \'acesso.db\'), MEC_MODO_TESTE_LOCAL=\'0\',\n        MEC_AMBIENTE=\'teste\', MEC_COOKIE_SEGURO=\'0\')\n    plugin = Grupo(manifesto, args.grupo, args.trabalho / (\'resultado_grupo_\' + str(args.grupo) + \'.json\'))\n    return int(pytest.main(argumentos_pytest() + [\'-v\', \'--durations=10\',\n        \'--basetemp=\' + str(diretorio / \'temporarios\')], plugins=[plugin]))\n\n\ndef distribuir(coletor, quantidade):\n    por_arquivo = defaultdict(list)\n    for nodeid in coletor.ids: por_arquivo[coletor.arquivos[nodeid]].append(nodeid)\n    grupos = {str(i): [] for i in range(1, quantidade + 1)}\n    for arquivo, ids in sorted(por_arquivo.items(), key=lambda par: (-len(par[1]), par[0])):\n        grupo = min(grupos, key=lambda nome: (len(grupos[nome]), int(nome)))\n        grupos[grupo].extend(ids)\n    return grupos\n\n\ndef validar_cobertura(manifesto, resultados):\n    executados = []\n    for numero, dados in resultados.items():\n        esperados = manifesto[\'grupos\'][str(numero)]\n        if dados[\'return_code\'] != 0 or Counter(dados[\'coletados\']) != Counter(manifesto[\'coletados\']):\n            raise RuntimeError(\'Falha ou coleção divergente no grupo \' + str(numero))\n        if Counter(dados[\'selecionados\']) != Counter(esperados):\n            raise RuntimeError(\'Seleção incompleta no grupo \' + str(numero))\n        for nodeid in esperados:\n            fases = dados[\'fases\'].get(nodeid, {})\n            if dados[\'chamadas\'].get(nodeid) != 1 or any(fases.get(f) != \'passed\' for f in (\'setup\', \'call\', \'teardown\')):\n                raise RuntimeError(\'Teste não aprovado integralmente uma única vez: \' + nodeid)\n        executados.extend(esperados)\n    if Counter(executados) != Counter(manifesto[\'coletados\']):\n        raise RuntimeError(\'A execução não corresponde à suíte completa coletada.\')\n    return len(executados)\n\n\ndef encerrar_filhos(processos):\n    for processo in processos:\n        if processo.poll() is None:\n            if os.name == \'nt\':\n                subprocess.run([\'taskkill\', \'/PID\', str(processo.pid), \'/T\', \'/F\'],\n                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=10)\n            else: processo.terminate()\n    for processo in processos:\n        try: processo.wait(timeout=5)\n        except subprocess.TimeoutExpired:\n            processo.kill(); processo.wait(timeout=5)\n\n\ndef executar_todos(args):\n    import pytest\n    inicio = time.monotonic()\n    coletor = Coletor(); buffer = io.StringIO()\n    with redirect_stdout(buffer), redirect_stderr(buffer):\n        codigo = int(pytest.main(argumentos_pytest() + [\'--collect-only\'], plugins=[coletor]))\n    (args.raiz / (args.prefixo + \'_pytest_coleta.log\')).write_text(buffer.getvalue(), encoding=\'utf-8\')\n    if codigo or not coletor.ids or len(set(coletor.ids)) != len(coletor.ids):\n        print(buffer.getvalue(), flush=True)\n        raise RuntimeError(\'Não foi possível conferir uma coleção completa e sem duplicatas.\')\n    quantidade = min(args.processos, len(set(coletor.arquivos.values())))\n    manifesto = {\'coletados\': coletor.ids, \'grupos\': distribuir(coletor, quantidade)}\n    gravar(args.trabalho / \'colecao.json\', manifesto)\n    print(\'PYTEST_PROCESSOS=\' + str(quantidade) + \'; TESTES_COLETADOS=\' + str(len(coletor.ids)), flush=True)\n    processos = []; leitores = []; logs = []; fila = queue.Queue(); encerrados = set()\n    def ler(numero, processo):\n        try:\n            for linha in processo.stdout: fila.put((numero, linha))\n        finally: fila.put((numero, None))\n    try:\n        for numero in range(1, quantidade + 1):\n            ambiente = {**os.environ, \'PYTHONUNBUFFERED\': \'1\', \'PYTHONIOENCODING\': \'utf-8\'}\n            comando = [sys.executable, \'-u\', str(Path(__file__).resolve()), \'--raiz\', str(args.raiz),\n                \'--trabalho\', str(args.trabalho), \'--prefixo\', args.prefixo, \'--grupo\', str(numero)]\n            processo = subprocess.Popen(comando, cwd=args.raiz, env=ambiente, stdout=subprocess.PIPE,\n                stderr=subprocess.STDOUT, text=True, encoding=\'utf-8\', errors=\'replace\', bufsize=1)\n            processos.append(processo)\n            logs.append((args.raiz / (args.prefixo + \'_pytest_grupo_\' + str(numero) + \'.log\')).open(\'w\', encoding=\'utf-8\', buffering=1))\n            leitor = threading.Thread(target=ler, args=(numero, processo), daemon=True); leitor.start(); leitores.append(leitor)\n        while len(encerrados) < quantidade:\n            try:\n                numero, linha = fila.get(timeout=.5)\n                if linha is None: encerrados.add(numero)\n                else:\n                    logs[numero - 1].write(linha)\n                    print(\'[\' + str(numero) + \'/\' + str(quantidade) + \'] \' + linha, end=\'\', flush=True)\n            except queue.Empty: pass\n            for numero, processo in enumerate(processos, 1):\n                if processo.poll() not in (None, 0):\n                    # O log integral de cada grupo permanece disponível para o diagnóstico.\n                    for leitor in leitores: leitor.join(timeout=.05)\n                    while not fila.empty():\n                        i, linha = fila.get_nowait()\n                        if linha is not None:\n                            logs[i - 1].write(linha); print(\'[\' + str(i) + \'/\' + str(quantidade) + \'] \' + linha, end=\'\', flush=True)\n                    raise RuntimeError(\'O grupo \' + str(numero) + \' reprovou a validação; confira seu log.\')\n        for processo in processos:\n            if processo.wait() != 0: raise RuntimeError(\'Um grupo de testes não concluiu com sucesso.\')\n        resultados = {numero: json.loads((args.trabalho / (\'resultado_grupo_\' + str(numero) + \'.json\')).read_text(encoding=\'utf-8\'))\n            for numero in range(1, quantidade + 1)}\n        total = validar_cobertura(manifesto, resultados)\n        resumo = {\'coletados\': total, \'aprovados\': total, \'processos\': quantidade,\n            \'todos_executados_uma_vez\': True, \'duracao_segundos\': round(time.monotonic() - inicio, 2)}\n        gravar(args.trabalho / \'pytest_resultado.json\', resumo)\n        print(\'PYTEST_COMPLETO_OK=True; APROVADOS=\' + str(total) + \'; EXECUCOES_UNICAS=True\', flush=True)\n        return 0\n    finally:\n        encerrar_filhos(processos)\n        for leitor in leitores: leitor.join(timeout=2)\n        for log in logs: log.close()\n        for processo in processos:\n            if processo.stdout is not None: processo.stdout.close()\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--raiz\', required=True, type=Path)\n    parser.add_argument(\'--trabalho\', required=True, type=Path)\n    parser.add_argument(\'--prefixo\', required=True)\n    parser.add_argument(\'--processos\', type=int, choices=(1, 2), default=2)\n    parser.add_argument(\'--grupo\', type=int, choices=(1, 2))\n    args = parser.parse_args(); args.raiz = args.raiz.resolve(); args.trabalho = args.trabalho.resolve()\n    os.chdir(args.raiz); sys.path.insert(0, str(args.raiz))\n    os.environ.pop(\'PYTEST_ADDOPTS\', None)\n    try: return executar_grupo(args) if args.grupo else executar_todos(args)\n    except Exception as erro:\n        print(\'ERRO_VALIDACAO_PARALELA=\' + str(erro), flush=True); return 1\n\n\nif __name__ == \'__main__\':\n    raise SystemExit(main())\n'

